static void poly_blocks(job_t *j, const unsigned char *m, size_t bytes) {
    const uint64_t mask = 0xfffffffffffULL;
    uint64_t r0=j->r0,r1=j->r1,r2=j->r2,s1=j->s1,s2=j->s2;
    uint64_t h0=j->h0,h1=j->h1,h2=j->h2, c;
